INSERT INTO `courses` VALUES (1,2,NULL,'beginner',0,'Lập trình Java cơ bản','Học Java từ cơ bản đến nâng cao',NULL,NULL,NULL,NULL,0.00,0,'approved','2026-04-16 15:21:57',NULL,'2026-05-10 08:29:19',NULL,2),(2,2,NULL,'beginner',0,'SQL cho người mới','Học SQL từ đầu',NULL,NULL,NULL,NULL,0.00,1,'approved','2026-04-16 15:21:57',NULL,NULL,NULL,1),(3,7,NULL,'beginner',0,'abc','aaaaaaaaaaa',NULL,NULL,NULL,'/uploads/courses/2026_04/file_69e656ec93e5e_1776703212.mp4',5000.00,1,'approved','2026-04-20 16:40:12',NULL,'2026-05-07 07:21:50',NULL,0),(4,7,NULL,'beginner',0,'Test 1','test ',NULL,NULL,NULL,'/uploads/courses/2026_04/file_69ea3ce31feff_1776958691.png',10000.00,1,'approved','2026-04-23 15:38:11',NULL,'2026-05-10 08:29:06',NULL,0),(5,7,1,'beginner',60,'Nhập môn lập trình','Nội dung thường bao gồm:\n•	Khái niệm về lập trình và ngôn ngữ lập trình \n•	Biến, kiểu dữ liệu, toán tử \n•	Cấu trúc điều kiện (if, switch) \n•	Vòng lặp (for, while) \n•	Hàm (Function) \n•	Mảng, chuỗi \n•	Thuật toán cơ bản và tư duy giải quyết vấn đề \n•	Làm việc với input/output \n•	Thực hành viết các chương trình đơn giản \nSau khóa học, học viên có thể:\n•	Hiểu cách hoạt động của chương trình \n•	Viết được các ứng dụng cơ bản \n•	Rèn luyện tư duy logic \n•	Làm nền tảng để học các công nghệ nâng cao như Web, Mobile, AI, Java, PHP, Python,... \nPhù hợp cho:\n•	Người mới bắt đầu \n•	Sinh viên CNTT \n•	Người muốn chuyển ngành sang lập trình \n•	Học sinh muốn tiếp cận công nghệ sớm. \n',NULL,NULL,NULL,'/uploads/courses/2026_05/img_69fc321a24a18_1778135578.png',0.00,0,'approved','2026-05-07 06:32:58',NULL,NULL,NULL,2),(6,7,2,'intermediate',5,'abc','bbbbb',NULL,NULL,NULL,'/uploads/courses/2026_05/img_69fc3e6a0207a_1778138730.png',5000.00,1,'hidden','2026-05-07 07:25:30',NULL,'2026-05-10 08:27:34',NULL,1),(7,16,3,'advanced',30,'learning AI','Hiểu về AI sâu hơn',NULL,NULL,NULL,'/uploads/courses/2026_05/img_69fd5b77e730a_1778211703.png',10000.00,1,'approved','2026-05-08 03:41:44',NULL,NULL,NULL,3),(8,7,3,'beginner',480,'Làm chủ AI & ChatGPT cho người mới bắt đầu','Khóa học giúp học viên hiểu và ứng dụng trí tuệ nhân tạo (AI) trong học tập, công việc và kinh doanh.\nHọc viên sẽ được hướng dẫn từ các khái niệm nền tảng đến cách sử dụng ChatGPT, tạo prompt hiệu quả, tự động hóa công việc và xây dựng mini project thực tế.\n\nSau khóa học, học viên có thể:\n\nHiểu cơ bản về AI và Generative AI\nSử dụng ChatGPT hiệu quả\nViết prompt chuyên nghiệp\nỨng dụng AI vào học tập và công việc\nTạo chatbot hoặc trợ lý AI đơn giản','','','','/uploads/courses/2026_05/img_6a06c9c4efcbf_1778829764.png',0.00,0,'approved','2026-05-15 06:46:44',NULL,NULL,NULL,3),(9,23,3,'beginner',12,'làm chủ AI','aaa','aa','aaa','aaa','/uploads/courses/2026_05/img_6a095f3f57ac6_1778999103.png',0.00,0,'pending','2026-05-17 06:25:03',NULL,'2026-05-17 08:32:36',NULL,0);
